// Susun notifikasi error untuk Steven + ambil kredensial Kirimi dari CONFIG.
//
// TITIK LEMAH (baca sticky note di workflow ini): node "Read CONFIG" di atas
// dipasangi onError: continueRegularOutput supaya kegagalan baca sheet TIDAK
// menghentikan notifikasi ini secara diam-diam. Tapi kalau CONFIG memang gagal
// dibaca, kita tidak punya kredensial Kirimi asli -- satu-satunya pilihan
// adalah jatuh ke PLACEHOLDER di bawah, yang KEMUNGKINAN BESAR akan gagal
// terkirim juga. Pesan yang disusun tetap menyebut kondisi ini secara eksplisit
// (bukan gagal diam-diam), supaya kalau notifikasi ini sampai, Steven tahu ada
// masalah ganda; kalau tidak sampai sama sekali, itulah sinyal untuk memantau
// log eksekusi workflow ini secara manual.
const FALLBACK = {
  kirimi_user_code: 'PLACEHOLDER_ISI_MANUAL',
  kirimi_secret: 'PLACEHOLDER_ISI_MANUAL',
  kirimi_device_id: 'PLACEHOLDER_ISI_MANUAL'
};

const e = $('Error Trigger').first().json;
const wfName = e.workflow?.name || 'VIRA Steven';
const execId = e.execution?.id || '-';
const node = e.execution?.error?.node?.name || e.execution?.lastNodeExecuted || '-';
const msg = String(e.execution?.error?.message || 'unknown error').substring(0, 300);
const url = e.execution?.url || '-';

// Kalau Read CONFIG gagal (onError: continueRegularOutput), outputnya adalah
// 1 item berisi { error: ... }, bukan rows CONFIG -- jadi cfgRows akan kosong
// dan configOk otomatis false.
const cfgRows = $input.all().map(i => i.json).filter(r => r && r.key !== undefined);
const cfg = {};
for (const r of cfgRows) {
  const k = String(r.key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : '';
}

const configOk = cfgRows.length > 0 && cfg.kirimi_user_code && cfg.kirimi_secret && cfg.kirimi_device_id
  && !String(cfg.kirimi_user_code).includes('ISI MANUAL');

const creds = configOk ? {
  user_code: String(cfg.kirimi_user_code).trim(),
  secret: String(cfg.kirimi_secret).trim(),
  device_id: String(cfg.kirimi_device_id).trim()
} : {
  user_code: FALLBACK.kirimi_user_code,
  secret: FALLBACK.kirimi_secret,
  device_id: FALLBACK.kirimi_device_id
};

// 2026-08-28: admin_phone kini dibaca dari CONFIG (dulu hardcode '6285171701168').
// Fallback tetap ada supaya notifikasi tidak hilang total kalau CONFIG gagal dibaca.
const ADMIN_FALLBACK = '6285171701168';
const adminPhone = String(cfg.admin_phone || '').trim() || ADMIN_FALLBACK;
const adminFromConfig = Boolean(String(cfg.admin_phone || '').trim());

let text = `🚨 [VIRA Personal] EKSEKUSI GAGAL\nWorkflow: ${wfName}\nNode: ${node}\nError: ${msg}\nExecution: ${execId}\n${url}\n\n⚠️ Ada pesan user yang kemungkinan TIDAK terbalas. Cek & balas manual.`;

if (!configOk) {
  text += `\n\n⚠️⚠️ CONFIG tidak terbaca / belum diisi -- notifikasi ini memakai kredensial PLACEHOLDER dan KEMUNGKINAN GAGAL TERKIRIM. Ini titik lemah jaring pengaman terakhir. Cek log eksekusi workflow "VIRA Personal — Error Notifier" secara manual dan pastikan tab CONFIG (kirimi_user_code/kirimi_secret/kirimi_device_id) sudah terisi.`;
}

return [{ json: {
  notif_text: text,
  admin_phone: adminPhone,
  kirimi_user_code: creds.user_code,
  kirimi_secret: creds.secret,
  kirimi_device_id: creds.device_id,
  config_ok: configOk,
  admin_from_config: adminFromConfig
} }];

// Kirimi bisa balas HTTP 200 tapi isinya gagal (device disconnect, nomor salah,
// kuota habis). n8n menganggap itu sukses -> tidak ada error -> Error Workflow
// tidak jalan -> tidak ada notifikasi sama sekali.
// Node ini sengaja throw supaya jalur fallback email ikut jalan.
const input = $input.first();
const r = input.json || {};

const isSuccess = r.status === true ||
                  r.success === true ||
                  (r.data && r.data.id) ||
                  (r.message && r.message !== 'error');

if (!isSuccess) {
  throw new Error('Kirimi API gagal: ' + JSON.stringify(r).slice(0, 500));
}

return [input];

// ============================================================
// Rangkai payload untuk GLOBAL - Email Fallback Notifier.
// Dipanggil saat node Kirimi gagal (HTTP error ATAU response 200-tapi-gagal).
// ============================================================
const TENANT = 'VIRA-PERSONAL';

const et = $('Error Trigger').first().json || {};
const composed = $('Compose Notif').first().json || {};
const notif = composed.notif_text || '';
const f = $input.first().json || {};

const reason = f.error?.message || f.error || f.message ||
               'Kirimi API tidak mengembalikan status sukses';

return [{
  json: {
    source: 'kirimi_fallback',
    tenant: TENANT,

    notif_text: notif,

    fail_node: 'Notify Admin Error (Kirimi)',
    fail_reason: String(reason).slice(0, 600),
    kirimi_response: JSON.stringify(f).slice(0, 800),

    // Kalau CONFIG gagal dibaca, kredensial Kirimi tadi PLACEHOLDER -- sebutkan
    // eksplisit supaya email menjelaskan kenapa WA-nya sudah pasti gagal.
    config_ok: composed.config_ok === true,
    admin_from_config: composed.admin_from_config === true,

    notifier_wf_name: $workflow.name,
    notifier_wf_id: $workflow.id,
    notifier_exec_id: $execution.id,

    orig_wf_name: et.workflow?.name || '-',
    orig_wf_id: et.workflow?.id || '',
    orig_exec_id: et.execution?.id || '-',
    orig_exec_url: et.execution?.url || '',
    orig_node: et.execution?.error?.node?.name || et.execution?.lastNodeExecuted || '-',
    orig_error: String(et.execution?.error?.message || '-').slice(0, 600)
  }
}];
